export type StickerPayload={kind:'sticker'|'gif';version:1;media_id:string;label?:string;catalog_id?:string;mime?:'image/webp'|'image/png'|'image/jpeg'|'image/gif'|'video/mp4'|'video/webm'};
export type ContactPayload={kind:'contact';version:1;username:string;display_name?:string};
export type DicePayload={kind:'dice';version:1;id:string;value:number;source:'server'|'device'};
export type PollPayload={kind:'poll';version:1;id:string;question:string;options:{id:string;text:string}[];multiple:boolean;quiz:boolean;expires_at:string;answer_commitment?:string};
export type PollVotePayload={kind:'poll_vote';version:1;poll_id:string;choices:string[];revision:number};
export type PollClosePayload={kind:'poll_close';version:1;poll_id:string;answer?:{option_id:string;salt:string}};
export type LocationPayload={kind:'location';version:1;id:string;latitude:number;longitude:number;live:boolean;expires_at:string};
export type LocationUpdatePayload={kind:'location_update';version:1;location_id:string;latitude:number;longitude:number;sequence:number};
export type LocationStopPayload={kind:'location_stop';version:1;location_id:string};
export type MessagePayload=StickerPayload|ContactPayload|DicePayload|PollPayload|PollVotePayload|PollClosePayload|LocationPayload|LocationUpdatePayload|LocationStopPayload;
export type PayloadMessage={id:string;room_id:string;sender_id:string;created_at:string;text?:string|null;type?:string;meta?:Record<string,unknown>|null;encrypted_content?:string|null;_decrypted?:boolean;hidden?:boolean;deleted?:boolean;deleted_at?:string};
export type PollState={poll:PollPayload;closed:boolean;counts:Record<string,number>;voters:number;answer:string|null;votes:Record<string,PollVotePayload>};
export type LocationState=LocationPayload&{sequence:number;active:boolean;expired:boolean};
export const PAYLOAD_PREFIX:string;
export const MAX_LIVE_LOCATION_MS:number;
export function validateMessagePayload(p:unknown):p is MessagePayload;
export function parseMessagePayload(text:unknown):MessagePayload|null;
export function encodeMessagePayload(p:MessagePayload):string;
export function secureDice(cryptoProvider?:Pick<Crypto,'getRandomValues'>):number;
export function expressiveId(cryptoProvider?:Pick<Crypto,'getRandomValues'>):string;
export function quizCommitment(option:string,salt:string,cryptoProvider?:Crypto):Promise<string>;
export function reducePoll(origin:PayloadMessage,events:PayloadMessage[],now?:number,cryptoProvider?:Crypto):Promise<PollState|null>;
export function reduceLocation(origin:PayloadMessage,events:PayloadMessage[],now?:number):LocationState|null;
export function isExpressiveControl(p:MessagePayload|null):boolean;
export function expressiveSummary(p:MessagePayload|null):string;
export const EMOJI_CATALOG:{emoji:string;terms:string}[];
export function searchEmoji(query?:string,recent?:string[],category?:string):typeof EMOJI_CATALOG;
export function isSecretRoom(room:unknown):boolean;
export function buildChatExport(options:{room:{id:string;title?:string|null};messages:PayloadMessage[];decode:(m:PayloadMessage)=>Promise<PayloadMessage>;acknowledged?:boolean;format?:'json'|'html';cancelled?:()=>boolean;attachments?:{message_id:string;name:string;mime:string;base64:string}[]}):Promise<string>;

export const EMOJI_CATEGORIES:{id:string;label:string}[];
